// ================= НАСТРОЙКИ АГЕНТА КВАЛИФИКАЦИИ =================
// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md и docs/04-scoring.md.
const config = {
  company: 'Название компании',
  offer: 'Что вы продаёте и кому — одним предложением. Модель сверяет с этим каждого лида.',
  ideal_customer: 'Компании 10–500 человек в B2B-услугах, торговле и производстве, которым нужна автоматизация продаж. Не подходят: студенты, частные лица, агентства-конкуренты, соискатели.',

  // Доступ
  agent_token: 'ЗАМЕНИТЕ_НА_ДЛИННУЮ_СЛУЧАЙНУЮ_СТРОКУ',
  debug_token: '',                    // заголовок x-agent-debug с этим значением — ответ с полной оценкой (для evals)

  // Таблица CRM: лист Leads
  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',
  dedupe_days: 90,                    // повторная заявка в этот срок — та же строка и тот же менеджер

  // Телефон
  phone_country_code: '380',          // для номеров без кода страны
  phone_national_prefix: '0',

  // Изучение сайта
  research_website: true,             // false — модель оценивает только по форме
  max_pages: 3,                       // сколько страниц сайта модель может открыть
  page_chars: 4000,                   // сколько текста страницы получает модель
  fetch_allow_private: false,         // не трогайте: запрет на внутренние адреса (защита от SSRF)

  // Рубрика: из чего складываются баллы. Вес — сколько баллов максимум. Сумма весов приводится к 100.
  rubric: [
    { id: 'fit', label: 'Подходит под идеального клиента', weight: 30, type: 'model', field: 'fit', points: { high: 1, medium: 0.5, low: 0 } },
    { id: 'intent', label: 'Ясный запрос и намерение купить', weight: 20, type: 'model', field: 'intent', points: { high: 1, medium: 0.5, low: 0 } },
    { id: 'size', label: 'Размер компании', weight: 15, type: 'model', field: 'company_size', points: { '1': 0, '2-10': 0.3, '11-50': 0.8, '51-200': 1, '201-1000': 1, '1000+': 0.7, unknown: 0.2 } },
    { id: 'urgency', label: 'Сроки', weight: 10, type: 'model', field: 'urgency', points: { now: 1, quarter: 0.6, later: 0.2, unknown: 0.2 } },
    { id: 'budget', label: 'Бюджет из формы', weight: 15, type: 'budget', min: 1000 },
    { id: 'corporate_email', label: 'Корпоративная почта', weight: 5, type: 'corporate_email' },
    { id: 'phone', label: 'Оставил телефон', weight: 5, type: 'present', field: 'phone' },
  ],
  hot_score: 70,
  warm_score: 40,
  // Красные флаги из оценки модели, которые снимают лида с маршрутизации
  disqualify_flags: ['spam', 'job_seeker', 'student', 'competitor', 'vendor_pitch'],

  // Менеджеры и сегменты. Новые лиды сегмента — по кругу между активными менеджерами.
  owners: [
    { id: 'anna', name: 'Анна', chat_id: 'ВСТАВЬТЕ_ID_ЧАТА_АННЫ', segments: ['smb'], active: true },
    { id: 'oleg', name: 'Олег', chat_id: 'ВСТАВЬТЕ_ID_ЧАТА_ОЛЕГА', segments: ['smb', 'enterprise'], active: true },
  ],
  // Сегмент: enterprise — если размер из списка или бюджет от суммы; иначе smb
  enterprise_sizes: ['201-1000', '1000+'],
  enterprise_budget: 20000,
  team_chat_id: 'ВСТАВЬТЕ_ID_ЧАТА',   // чат отдела: горячие лиды, дубли, лиды без менеджера, ошибки

  // Уточняющее письмо лиду — только если включено и заявке не хватает данных
  clarify_by_email: false,            // нужен SMTP в узле Clarify Email
  clarify_from_name: 'Команда',
  clarify_tiers: ['warm'],            // каким уровням писать

  free_email_domains: ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com', 'ukr.net', 'i.ua', 'meta.ua', 'mail.ru', 'yandex.ru', 'proton.me', 'protonmail.com', 'gmx.de', 'gmx.net', 'aol.com', 'live.com', 'me.com'],
};

return [{ json: { config, input: $input.first().json } }];

// Intake: принимает заявку с любой формы, приводит поля к одному виду, отсекает мусор.
// ---- разбор адреса без глобального URL (его нет в песочнице узла Code) ----
function parseUrl(text) {
  const m = /^(https?|ftp|file):\/\/(\[[^\]]*\]|[^/?#:@\s]*)(?::(\d{1,5}))?([/?#][^\s]*)?$/i.exec(String(text || '').trim());
  if (!m) return null;
  const protocol = m[1].toLowerCase() + ':';
  const hostname = m[2].toLowerCase();
  const path = m[4] || '/';
  return { protocol, hostname, port: m[3] || '', href: `${protocol}//${hostname}${m[3] ? ':' + m[3] : ''}${path}` };
}

const { config, input } = $input.first().json;
const headers = input.headers || {};
const body = typeof input.body === 'object' && input.body ? input.body : {};
const query = input.query || {};
const out = (route, extra) => [{ json: { route, ...extra } }];

const token = headers['x-agent-token'] || body.token || query.token;
if (!config.agent_token || config.agent_token.startsWith('ЗАМЕНИТЕ') || token !== config.agent_token) return out('deny', {});
const debug = Boolean(config.debug_token) && headers['x-agent-debug'] === config.debug_token;

// Поля с любых форм: Tilda, Webflow, WordPress, Google Forms, своя форма
const flat = {};
for (const [k, v] of Object.entries({ ...query, ...body })) flat[String(k).toLowerCase().replace(/[\s_-]+/g, '')] = Array.isArray(v) ? v.join(', ') : v;
const pick = (...keys) => { for (const k of keys) if (flat[k] !== undefined && String(flat[k]).trim()) return String(flat[k]).trim(); return ''; };
const lead = {
  name: pick('name', 'имя', 'fullname', 'yourname', 'contactname').slice(0, 120),
  email: pick('email', 'почта', 'mail', 'youremail').toLowerCase().slice(0, 200),
  phone: pick('phone', 'телефон', 'tel', 'phonenumber', 'mobile').slice(0, 40),
  company: pick('company', 'компания', 'organization', 'organisation', 'companyname').slice(0, 200),
  website: pick('website', 'сайт', 'site', 'url', 'companywebsite').slice(0, 300),
  message: pick('message', 'сообщение', 'comment', 'comments', 'комментарий', 'text', 'request', 'запрос').slice(0, 3000),
  budget: pick('budget', 'бюджет').slice(0, 100),
  source: pick('source', 'utmsource', 'источник', 'formname', 'form') .slice(0, 100) || 'web',
};

// Ловушка для ботов: скрытое поле, которое человек не заполнит
if (pick('hp', 'honeypot', 'fax', 'companywebsitehp')) return out('spam', { debug, reason: 'honeypot' });
// Tilda перед сохранением вебхука шлёт test=test — отвечаем 200, в CRM не пишем
if (!lead.email && !lead.phone && String(flat.test || '').toLowerCase() === 'test') return out('spam', { debug, reason: 'tilda_test' });
if (!lead.email && !lead.phone) return out('bad', { error: 'Нужен email или телефон' });
if (lead.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) return out('bad', { error: 'Email выглядит неверно' });

// Телефон к международному виду
if (lead.phone) {
  let d = lead.phone.replace(/[^\d+]/g, '');
  if (d.startsWith('+')) d = d.slice(1);
  else if (d.startsWith('00')) d = d.slice(2);
  else if (config.phone_national_prefix && d.startsWith(config.phone_national_prefix)) d = config.phone_country_code + d.slice(config.phone_national_prefix.length);
  else if (d.length <= 9) d = config.phone_country_code + d;
  lead.phone = d.length >= 8 ? '+' + d : '';
}

// Домен компании: из сайта, иначе из корпоративной почты
const emailDomain = lead.email.split('@')[1] || '';
const free = (config.free_email_domains || []).includes(emailDomain);
let domain = '';
if (lead.website) {
  const u = parseUrl(/^https?:\/\//i.test(lead.website) ? lead.website : 'https://' + lead.website);
  domain = u ? u.hostname.replace(/^www\./, '') : '';
}
if (!domain && emailDomain && !free) domain = emailDomain;
lead.domain = domain;
lead.corporate_email = Boolean(emailDomain) && !free;
if (lead.website && !/^https?:\/\//i.test(lead.website)) lead.website = 'https://' + lead.website;
if (!lead.website && domain) lead.website = 'https://' + domain;

// Двойной клик и повтор формы в течение 10 минут — одна заявка
const store = $getWorkflowStaticData('global');
store.recent = store.recent || {};
const now = Date.now();
for (const [k, t] of Object.entries(store.recent)) if (now - t > 600000) delete store.recent[k];
const key = [lead.email, lead.phone, lead.message.slice(0, 200)].join('|');
if (store.recent[key]) return out('repeat', { debug });
store.recent[key] = now;

let h = 2166136261;
for (const ch of key + now) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
lead.lead_id = 'L-' + now.toString(36).toUpperCase().slice(-5) + h.toString(36).toUpperCase().slice(0, 4);
lead.received = new Date(now).toISOString();
return out('ok', { debug, lead });

